    // At the start of each iteration, the stack contains only unmatched characters
    // and removal_count reflects the number of pairs removed so far.
    let mut stack: Vec<char> = Vec::new();
    let mut removal_count = 0;

    // Loop invariant: At the start of each iteration, `removal_count` is the number of pairs removed
    // and `stack` contains only unmatched characters from the input `s`.
    // The length of `stack` is always less than or equal to the length of `s`.
    // The loop will iterate over each character in `s`.
